data = []
for row in value:  
    keys = row.keys()  
    formatted_rows = []
    for key, v in row.items():
        if key == "color":
            style = {"backgroundColor": v, "color": v} 
            formatted_rows.append({"value": v, "style": style})
        else:
            formatted_rows.append({"value": v, "style": {}}) 

    row_dict = dict(zip(keys, formatted_rows))
    data.append(row_dict) 
return data
